{
  "a_sentences": [
    {
      "a_text": "Le Tribunal fédéral rappelle que l’exception de récusation ne vise que des personnes physiques et non un collège ou une institution entière.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Les motifs de récusation doivent être exposés de façon précise et se rapporter à des personnes déterminées.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Les faits fondant la récusation doivent être rendus vraisemblables à l’égard de chaque personne visée.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Même si l’ensemble d’un tribunal devait être considéré comme partial, chaque membre doit être visé individuellement par des motifs de récusation précis.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Un recours qui s’adresse de façon générale à un tribunal entier ou à tous ses membres est irrecevable.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "L’argumentation des recourantes est rejetée.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La juridiction cantonale a à juste titre déclaré le recours en récusation irrecevable.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Il n’y a pas lieu de critiquer le refus de la juridiction cantonale d’entrer en matière sur la demande de récusation, formulée de façon globale, sans qu’aucun motif individuel ne soit avancé.",
      "b_propositions": ["P8"]
    }
  ]
}
